import os,json
run='RUNS/892/2026-10-04_20-44-36'
out={'run_files':[],'json':{},'control_state':{}}
for dp,ds,fs in os.walk(run):
    for n in fs:
        p=os.path.join(dp,n)
        out['run_files'].append(p.replace('\\','/'))
for p in [
    run+'/RUN_MANIFEST.json',
    run+'/QA/RG_POSTRUN_QA.json',
    run+'/QA/DIALOGUE_TABLE.json',
    run+'/QA/RG_PERFORMANCE_PROFILE.json'
]:
    try:
        out['json'][p]=json.load(open(p,encoding='utf-8'))
    except Exception as e:
        out['json'][p]={'error':repr(e)}
if os.path.isdir('CONTROL/STATE'):
    for n in sorted(os.listdir('CONTROL/STATE')):
        p='CONTROL/STATE/'+n
        try:
            if os.path.isfile(p) and os.path.getsize(p)<=200000:
                txt=open(p,encoding='utf-8',errors='replace').read()
                try: val=json.loads(txt)
                except Exception: val=txt[-12000:]
                out['control_state'][n]=val
            elif os.path.isdir(p):
                out['control_state'][n]={'type':'dir','items':sorted(os.listdir(p))[:100]}
        except Exception as e:
            out['control_state'][n]={'error':repr(e)}
print(json.dumps(out,ensure_ascii=False))
